SELECT sku, productName, packSize, flowType, unitsPerCase, caseWeightKg, sellingPriceInr, costPriceInr, gtin, dc_slot
FROM store.products
ORDER BY sku;

SELECT sku, gtin, name, pack, case_units, case_kg, flow, dc_slot, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT SUM(units_sold) AS total_bags_sold
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date <= DATE '2026-06-30';
